def check_type_rejection(name, returncode, output):
    if returncode != 1 or output != EXPECTED_TYPE_REJECTIONS[name]:
        raise RuntimeError(f"Unexpected type-rejection diagnostic: {name}")


def parse_axiom_audit(output):
    records = []
    pending = None
    continuation = r"\s*[A-Za-z_][\w.]*(?:,\s*[A-Za-z_][\w.]*)*(?:,|\])\s*"
    for line in output.splitlines():
        if pending is not None:
            if not re.fullmatch(continuation, line):
                raise RuntimeError(f"Unexpected axiom continuation: {line}")
            pending += " " + line.strip()
            if line.rstrip().endswith("]"):
                records.append(pending)
                pending = None
        elif re.fullmatch(r"'[^']+' depends on axioms: \[[^\]]*,", line):
            pending = line
        else:
            records.append(line)
    if pending is not None:
        raise RuntimeError("Unterminated axiom audit record")
    audits = {}
    for line in records:
        match = re.fullmatch(r"'([^']+)' (does not depend on any axioms|depends on axioms: \[(.*)\])", line)
        if not match:
            raise RuntimeError(f"Unexpected axiom audit output: {line}")
        axioms = set(match[3].split(", ")) if match[3] else set()
        if not axioms <= ALLOWED_AXIOMS:
            raise RuntimeError(f"Unapproved axioms for {match[1]}: {axioms}")
        if match[1] in audits:
            raise RuntimeError(f"Duplicate axiom audit output: {match[1]}")
        audits[match[1]] = sorted(axioms)
    return audits


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--lake", default="lake")
    args = parser.parse_args()
    evidence = ROOT / ".lake" / "verification"
    evidence.mkdir(parents=True, exist_ok=True)
    report_path = evidence / "report.json"
    report_path.unlink(missing_ok=True)
    source_paths = [ROOT / name for name in (
        "CssSemantics.lean", "coverage.json", "lakefile.lean", "lake-manifest.json", "lean-toolchain", "check.py", "README.md", "browser_check.py", "browser/runner.js", "browser/computed.js", "browser/index.html", "import_browser_check.py", "browser/import_server.py", "browser/imports.js", "browser/import-discrepancies.json", "browser/rollback-import-discrepancies.json", "author_sheets_browser_check.py", "browser/author_sheets_server.py", "browser/author_sheets.js", "browser/author-sheets-discrepancies.json", "attached_style_browser_check.py", "browser/attached_style_server.py", "browser/attached_style.js", "browser/attached-style-discrepancies.json", "named_container_browser_check.py", "browser/named_container_server.py", "browser/named_container.js", "browser/named-container-discrepancies.json", "origin_cascade_browser_check.py", "browser/origin_cascade_server.py", "browser/origin_cascade.js", "browser/origin-cascade-discrepancies.json", "ARTIFACT.md", "source_scope_browser_check.py", "browser/source_scope_server.py", "browser/source_scope.js", "browser/source-scope-discrepancies.json", "owner_scope_browser_check.py", "browser/owner_scope_server.py", "browser/owner_scope.js", "browser/owner-scope-discrepancies.json", "import_scope_browser_check.py", "browser/import_scope_server.py", "browser/import_scope.js", "browser/import-scope-discrepancies.json")]
    source_paths += sorted((ROOT / "CssSemantics").rglob("*.lean"))
    source_paths += sorted((ROOT / "tests").rglob("*.lean"))

    def source_hashes():
        return {str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()
                for path in source_paths}

    before_hashes = source_hashes()
    commands = {}

    def run(name, command, expected_success=True):
        result = subprocess.run(command, cwd=ROOT, capture_output=True, text=True)
        output = result.stdout + result.stderr
        (evidence / f"{name}.log").write_text(output)
        commands[name] = {"argv": command, "returncode": result.returncode,
                          "log_sha256": hashlib.sha256(output.encode()).hexdigest()}
        if (result.returncode == 0) != expected_success:
            raise RuntimeError(f"Unexpected exit {result.returncode}: {name}\n{output}")
        return output

    version = run("toolchain", [args.lake, "env", "lean", "--version"]).strip()
    expected_version = (ROOT / "lean-toolchain").read_text().strip().split(":v")[1]
    if f"version {expected_version}," not in version:
        raise RuntimeError(f"Wrong Lean version: {version}")
    run("build", [args.lake, "build"])
    examples = run("executable-examples", [args.lake, "env", "lean", "--run", "tests/RunExamples.lean"])
    if any(type(value) is not bool for _, value in EXECUTABLE_CASES):
        raise RuntimeError("Executable case expectations must be Boolean")
    expected_examples = [f"PASS {name}: {str(value).lower()}" for name, value in EXECUTABLE_CASES]
    if examples.splitlines() != expected_examples:
        raise RuntimeError("Executable case names, results, or coverage changed")
    audit = run("axioms", [args.lake, "env", "lean", "tests/Audit.lean"])
    expected_names = re.findall(r"#print axioms (\S+)", (ROOT / "tests/Audit.lean").read_text())
    declared_theorems = set()
    for path in sorted((ROOT / "CssSemantics").rglob("*.lean")):
        scopes = []
        for raw_line in path.read_text().splitlines():
            line = raw_line.strip()
            namespace = re.fullmatch(r"namespace (\S+)", line)
            ending = re.fullmatch(r"end(?: (\S+))?", line)
            theorem = re.match(r"theorem (\S+)", line)
            if namespace:
                scopes.append(("namespace", namespace[1]))
            elif line == "mutual":
                scopes.append(("mutual", None))
            elif ending:
                if not scopes:
                    raise RuntimeError(f"Unexpected scope end in {path}")
                kind, name = scopes.pop()
                if ending[1] is not None and (kind != "namespace" or name != ending[1]):
                    raise RuntimeError(f"Mismatched namespace end in {path}")
            elif theorem:
                namespaces = [name for kind, name in scopes if kind == "namespace"]
                declared_theorems.add(".".join([*namespaces, theorem[1]]))
        if scopes:
            raise RuntimeError(f"Unclosed scope in {path}")
    if set(expected_names) != declared_theorems:
        raise RuntimeError("Axiom audit does not cover the exact named theorem set: "
                           f"missing={sorted(declared_theorems - set(expected_names))}, "
                           f"extra={sorted(set(expected_names) - declared_theorems)}")
    coverage = json.loads((ROOT / "coverage.json").read_text())
    spec_ids = {spec["id"] for spec in coverage["specifications"]}
    feature_ids = [feature["id"] for feature in coverage["features"]]
    if len(feature_ids) != len(set(feature_ids)):
        raise RuntimeError("Duplicate coverage feature")
    for feature in coverage["features"]:
        if feature["status"] not in {"checked_fragment", "unsupported"}:
            raise RuntimeError(f"Unknown coverage status: {feature['id']}")
        if feature["status"] == "checked_fragment" and not feature["theorems"]:
            raise RuntimeError(f"Checked fragment has no theorem: {feature['id']}")
        if not set(feature["theorems"]) <= declared_theorems:
            raise RuntimeError(f"Unknown coverage theorem: {feature['id']}")
        if not set(feature["specifications"]) <= spec_ids:
            raise RuntimeError(f"Unknown coverage specification: {feature['id']}")
        if any(not (ROOT / "CssSemantics" / module).is_file() for module in feature["modules"]):
            raise RuntimeError(f"Unknown coverage module: {feature['id']}")
    if len(expected_names) != len(set(expected_names)):
        raise RuntimeError("Duplicate axiom audit declaration")
    audits = parse_axiom_audit(audit)
    if set(audits) != set(expected_names):
        raise RuntimeError("Axiom audit declaration set mismatch")
    rejection = run("negative-child", [args.lake, "env", "lean", "tests/RejectDescendantAsChild.lean"], False)
    check_type_rejection("negative-child", commands["negative-child"]["returncode"], rejection)
    sibling_rejection = run("negative-adjacent", [args.lake, "env", "lean", "tests/RejectFollowingAsAdjacent.lean"], False)
    check_type_rejection("negative-adjacent", commands["negative-adjacent"]["returncode"], sibling_rejection)
    hashes = source_hashes()
    if hashes != before_hashes:
        raise RuntimeError("Source files changed during verification")
    report = {"status": "pass", "lean": version, "declaration_axioms": audits,
              "negative_child_control": "rejected with intended type mismatch",
              "negative_adjacent_control": "rejected with intended type mismatch",
              "source_sha256": hashes, "commands": commands,
              "executable_cases": [{"name": name, "result": value} for name, value in EXECUTABLE_CASES],
              "executable_case_count": len(EXECUTABLE_CASES),
              "browser_refinement_proved": False,
              "spec_translation_mechanically_proved": False}
    report_path.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n")
    print(f"PASS: {len(audits)} declarations audited; child and adjacent negative controls rejected.")
    print(report_path)


if __name__ == "__main__":
    main()
